<script setup>
import { usePage } from '@inertiajs/vue3';
const isStaff=usePage().props.auth.user?.permissions?.includes('clients.view-any');
import { ref } from 'vue';
import axios from 'axios';
import { Link, router } from '@inertiajs/vue3';
import AppLayout from '@/Layouts/AppLayout.vue';
import PrimaryButton from '@/Components/PrimaryButton.vue';
import ConfirmationModal from '@/Components/ConfirmationModal.vue';
const props = defineProps({ family: Object, profile: Object });
const busy = ref(false); const error = ref(''); const pending = ref(null);
const form = ref({email: '', relationship: '', scopes: ['view'], expires_on: ''});
const scopeLabels = {view:'Vedere le pratiche', documents:'Consultare e scaricare documenti',upload:'Caricare documenti',message:'Inviare messaggi',book:'Prenotare appuntamenti'};
const statuses = {active:'Attiva',pending:'In attesa di accettazione',expired:'Scaduta',revoked:'Revocata'};
async function run(method,url,body) {busy.value=true;error.value='';try {await axios({method,url,data:body});pending.value=null;router.reload();}catch(e){error.value=Object.values(e.response?.data?.errors??{}).flat().join(' ')||e.response?.data?.message||'Operazione non riuscita.';}finally{busy.value=false;}}
function grant(){run('post',route('family.grant',props.profile.client.id),{...form.value,expires_on:form.value.expires_on||null});}
function page(key,number){router.get(route('family.profile',props.profile.client.id),{[key]:number},{preserveScroll:true});}
</script>
<template><AppLayout title="Familiari e deleghe"><div v-if="isStaff && !family.profiles.length" class="mb-6 rounded-2xl border bg-white p-5 dark:bg-gray-800 dark:text-gray-100"><h3 class="text-lg font-semibold">Gestisci le deleghe dalla scheda cliente</h3><p class="my-3">Questo spazio mostra i profili personali e le deleghe che hai ricevuto. Per concedere una delega a un familiare, apri il cliente interessato.</p><Link :href="route('clients.index')" class="inline-flex min-h-12 items-center rounded-xl bg-blue-700 px-5 text-white">Apri clienti</Link></div><template #header><h2 class="text-xl font-semibold text-gray-800 dark:text-gray-100">Familiari e deleghe</h2></template><div class="mx-auto max-w-5xl space-y-6 px-4 py-8 sm:px-6 dark:text-gray-100">
<p class="text-sm text-gray-600 dark:text-gray-300">Ogni delega richiede l’accettazione del destinatario. Puoi scegliere le operazioni consentite, una scadenza e revocarla in qualsiasi momento.</p>
<p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-red-800">{{error}}</p>
<section v-if="family.invitations.length" class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h3 class="text-lg font-semibold">Inviti ricevuti</h3><article v-for="invite in family.invitations" :key="invite.id" class="space-y-3 border-t pt-4"><strong>{{invite.client.first_name}} {{invite.client.last_name}}</strong><p>{{invite.scopes.map(scope=>scopeLabels[scope]).join(' · ')}}</p><p>Scade il {{new Date(invite.expires_at).toLocaleDateString('it-IT')}}</p><div class="flex flex-wrap gap-3"><PrimaryButton :disabled="busy" @click="run('post',route('family.accept',invite.id))">Accetta delega</PrimaryButton><button :disabled="busy" @click="pending={client:invite.client.id,id:invite.id}" class="min-h-12 rounded-lg border px-4">Rifiuta</button></div></article></section>
<nav aria-label="Profili familiari" class="flex flex-wrap gap-3"><Link v-for="client in family.profiles" :key="client.id" :href="route('family.profile',client.id)" :aria-current="profile?.client.id===client.id?'page':undefined" class="min-h-12 rounded-xl border px-4 py-3" :class="profile?.client.id===client.id?'bg-blue-600 text-white':'bg-white text-blue-700 dark:bg-gray-800 dark:text-blue-300'">{{client.first_name}} {{client.last_name}} {{family.own_client_id===client.id?'(tu)':''}}</Link></nav>
<p v-if="!profile" class="rounded-2xl border bg-white p-6 text-gray-600 dark:bg-gray-800 dark:text-gray-300">Seleziona un profilo per vedere pratiche e documenti. Gli inviti accettati compaiono qui.</p>
<template v-if="profile"><div class="flex flex-wrap items-center justify-between gap-3"><h3 class="text-xl font-semibold">{{profile.client.first_name}} {{profile.client.last_name}}</h3><Link v-if="profile.can_book" :href="route('booking.index',{client_profile_id:profile.client.id})" class="min-h-12 rounded-xl bg-blue-600 px-4 py-3 font-semibold text-white">Prenota un orario disponibile</Link></div>
<section class="space-y-3 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h4 class="font-semibold">Pratiche</h4><p v-if="!profile.practices.data.length">Nessuna pratica.</p><Link v-for="practice in profile.practices.data" :key="practice.id" :href="route('practices.workspace',practice.id)" class="block min-h-12 border-t py-4 text-blue-700 dark:text-blue-300">{{practice.type}} · {{practice.tracking_code}} · {{practice.reference_year}}</Link><div v-if="profile.practices.last_page>1" class="flex justify-between"><button :disabled="profile.practices.current_page===1" @click="page('practice_page',profile.practices.current_page-1)" class="min-h-12 px-4">Precedente</button><span>{{profile.practices.current_page}} / {{profile.practices.last_page}}</span><button :disabled="profile.practices.current_page===profile.practices.last_page" @click="page('practice_page',profile.practices.current_page+1)" class="min-h-12 px-4">Successiva</button></div></section>
<section v-if="profile.can_documents" class="space-y-3 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h4 class="font-semibold">Documenti del profilo</h4><p v-if="!profile.documents.data.length">Nessun documento.</p><a v-for="document in profile.documents.data" :key="document.id" :href="route('family.download',{client:profile.client.id,document:document.id})" class="block min-h-12 border-t py-4 text-blue-700 underline dark:text-blue-300">{{document.original_name}}</a><div v-if="profile.documents.last_page>1" class="flex justify-between"><button :disabled="profile.documents.current_page===1" @click="page('document_page',profile.documents.current_page-1)" class="min-h-12 px-4">Precedente</button><span>{{profile.documents.current_page}} / {{profile.documents.last_page}}</span><button :disabled="profile.documents.current_page===profile.documents.last_page" @click="page('document_page',profile.documents.current_page+1)" class="min-h-12 px-4">Successiva</button></div></section>
<section v-if="profile.activity" class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h4 class="font-semibold">Storico modifiche e accessi</h4><p v-if="!profile.activity.total">Nessuna attività registrata.</p><ol class="divide-y"><li v-for="entry in profile.activity.data" :key="entry.id" class="py-3"><strong>{{entry.actor?.name || 'Utente non più disponibile'}}</strong><p>{{entry.action.startsWith('document.')?'Attività documento':entry.action.startsWith('delegation.')?'Attività delega':entry.action.startsWith('client.')?'Modifica anagrafica':'Attività pratica'}} · {{new Date(entry.created_at).toLocaleString('it-IT')}}</p><p v-if="entry.metadata?.fields?.length" class="text-sm text-gray-500">Campi: {{entry.metadata.fields.join(', ')}}</p></li></ol><div v-if="profile.activity.last_page>1" class="flex justify-between"><button :disabled="profile.activity.current_page===1" @click="page('activity_page',profile.activity.current_page-1)" class="min-h-12 px-4">Precedenti</button><span>{{profile.activity.current_page}} / {{profile.activity.last_page}}</span><button :disabled="profile.activity.current_page===profile.activity.last_page" @click="page('activity_page',profile.activity.current_page+1)" class="min-h-12 px-4">Successivi</button></div></section><template v-if="profile.can_manage"><section class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h4 class="font-semibold">Deleghe concesse</h4><p v-if="!profile.delegations.length">Nessuna delega.</p><article v-for="delegation in profile.delegations" :key="delegation.id" class="space-y-2 border-t py-4"><strong>{{delegation.delegate?.name}} · {{delegation.delegate?.email}}</strong><p>{{statuses[delegation.status]}} · Scadenza {{new Date(delegation.expires_at).toLocaleDateString('it-IT')}}</p><p>{{delegation.scopes.map(scope=>scopeLabels[scope]).join(' · ')}}</p><button v-if="['active','pending'].includes(delegation.status)" :disabled="busy" @click="pending={client:profile.client.id,id:delegation.id}" class="min-h-12 rounded-lg border border-red-600 px-4 text-red-700 dark:text-red-300">Revoca delega</button></article></section>
<form @submit.prevent="grant" class="space-y-4 rounded-2xl border bg-white p-5 dark:border-gray-700 dark:bg-gray-800"><h4 class="font-semibold">Invita un familiare</h4><label class="block text-sm">Email del familiare già registrato<input v-model="form.email" required type="email" maxlength="255" class="mt-2 block w-full rounded-lg border-gray-300 dark:bg-gray-900" /></label><label class="block text-sm">Relazione (facoltativa)<input v-model="form.relationship" maxlength="80" class="mt-2 block w-full rounded-lg border-gray-300 dark:bg-gray-900" /></label><fieldset class="space-y-3"><legend class="mb-2 text-sm">Operazioni consentite</legend><label v-for="(label,scope) in scopeLabels" :key="scope" class="flex min-h-12 items-center gap-3"><input v-model="form.scopes" :value="scope" type="checkbox" :disabled="scope==='view'" class="h-5 w-5 rounded" />{{label}}</label></fieldset><label class="block text-sm">Scadenza (predefinita: un anno)<input v-model="form.expires_on" type="date" :min="new Date(Date.now()+86400000).toISOString().slice(0,10)" class="mt-2 block rounded-lg border-gray-300 dark:bg-gray-900" /></label><p class="text-sm text-gray-500">Un nuovo invito allo stesso destinatario sostituisce la delega e richiede una nuova accettazione.</p><PrimaryButton :disabled="busy">Invia invito</PrimaryButton></form></template></template>
</div><ConfirmationModal :show="!!pending" @close="!busy&&(pending=null)"><template #title>Revocare la delega?</template><template #content>L’accesso al profilo e alle sue pratiche terminerà subito.</template><template #footer><button :disabled="busy" @click="pending=null" class="min-h-12 px-4">Annulla</button><PrimaryButton :disabled="busy" @click="run('delete',route('family.revoke',{client:pending.client,delegation:pending.id}))">Conferma</PrimaryButton></template></ConfirmationModal></AppLayout></template>
